// Redline engine: asks the model for a grounded review, then checks it. Scores are
// computed here from the clause library, never taken from the model.
import { CLAUSES, CLAUSE_BY_ID, CONTRACT_TYPES, RISK_WEIGHT, BASE_RISK } from './kb';
import type { ContractType, Risk } from './kb';

export const MAX_CHARS = 60000;

export interface RawFinding {
  library_id?: string;
  quote?: string;
  risk?: string;
  explanation?: string;
  rewrite?: string;
}

export interface RawDate {
  label?: string;
  date?: string;
  when?: string;
  kind?: string;
}

export interface RawReview {
  contract_type?: string;
  title?: string;
  counterparty?: string;
  findings?: RawFinding[];
  dates?: RawDate[];
}

export interface Finding {
  library_id: string | null;
  clause: string;
  risk: Risk;
  confidence: 'library' | 'review_recommended';
  source: string;
  quote: string;
  quote_verified: boolean;
  explanation: string;
  rewrite: string;
  weight: number;
}

export interface KeyDate {
  label: string;
  date: string | null;
  when: string;
  kind: string;
}

export interface Review {
  contract_type: ContractType;
  contract_label: string;
  title: string;
  counterparty: string;
  risk: number;
  level: 'low' | 'medium' | 'high';
  findings: Finding[];
  dates: KeyDate[];
  truncated: boolean;
}

const TYPES = Object.keys(CONTRACT_TYPES) as ContractType[];
const RISKS: Risk[] = ['high', 'medium', 'low'];
const DATE_KINDS = ['renewal', 'notice_deadline', 'payment', 'exclusivity_end', 'term_end', 'other'];

export const REVIEW_SCHEMA = {
  type: 'object',
  properties: {
    contract_type: { type: 'string', enum: TYPES },
    title: { type: 'string' },
    counterparty: { type: 'string' },
    findings: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          library_id: { type: 'string' },
          quote: { type: 'string' },
          risk: { type: 'string', enum: RISKS },
          explanation: { type: 'string' },
          rewrite: { type: 'string' },
        },
        required: ['library_id', 'quote', 'risk', 'explanation', 'rewrite'],
      },
    },
    dates: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          label: { type: 'string' },
          date: { type: 'string' },
          when: { type: 'string' },
          kind: { type: 'string', enum: DATE_KINDS },
        },
        required: ['label', 'date', 'when', 'kind'],
      },
    },
  },
  required: ['contract_type', 'title', 'counterparty', 'findings', 'dates'],
};

const LIBRARY_TEXT = CLAUSES.map(c => `${c.id} | ${c.library} | ${c.name} | ${c.risk} | ${c.exploit}`).join('\n');

export const REVIEW_SYSTEM = [
  'You are Redline, a contract-risk reviewer for people without a lawyer on retainer. You explain risk like a sharp friend: direct, a little cheeky, never condescending, never alarmist. You are not a lawyer and never give legal advice.',
  'Work only from the contract text you are given. Never invent clauses, numbers, dates or laws.',
].join(' ');

export function reviewPrompt(opts: { side?: string; city?: string; state?: string; who?: string }): string {
  const side = opts.side === 'buyer'
    ? 'the paying customer'
    : opts.side === 'seller'
      ? 'the provider being paid'
      : 'the individual signer (the weaker party, usually the athlete, creator, performer, employee, tenant, borrower or user)';
  return [
    `Review the contract for risks to ${side}.`,
    opts.who ? `The signer describes themselves as: ${opts.who}.` : '',
    opts.state ? `They are signing from ${[opts.city, opts.state].filter(Boolean).join(', ')}.` : '',
    '',
    `1. contract_type: one of ${TYPES.join(', ')}.`,
    '2. title: a short name for the contract, e.g. "NIL endorsement agreement". counterparty: the other party\'s name, or "".',
    '3. findings: every clause that is risky for the signer. For each:',
    '   - library_id: the id of the best-matching entry in the CLAUSE LIBRARY below. Use "" only if no entry fits.',
    '   - quote: the risky sentence copied exactly from the contract, at most 300 characters.',
    '   - risk: high, medium or low.',
    '   - explanation: one or two plain-English sentences on what could go wrong for the signer.',
    '   - rewrite: replacement clause text the signer could propose instead. Concrete and fair, ready to paste.',
    '   Order findings from most to least risky. Do not flag standard, balanced clauses.',
    '4. dates: every date, deadline or time window in the contract (renewals, notice deadlines, payment due dates, exclusivity end, term end).',
    '   label: what it is. date: YYYY-MM-DD if the contract states an exact date, else "". when: the deadline as written, e.g. "30 days before renewal". kind: one of ' + DATE_KINDS.join(', ') + '.',
    '',
    'CLAUSE LIBRARY (id | library | clause | risk | common exploit):',
    LIBRARY_TEXT,
  ].filter(Boolean).join('\n');
}

const norm = (s: string) => s.replace(/[‘’]/g, "'").replace(/[“”]/g, '"').replace(/\s+/g, ' ').trim().toLowerCase();

function clip(s: unknown, n: number): string {
  const t = String(s ?? '').replace(/\s+/g, ' ').trim();
  return t.length > n ? t.slice(0, n - 1) + '…' : t;
}

export function finalize(raw: RawReview, text: string, truncated: boolean): Review {
  const type: ContractType = TYPES.includes(raw.contract_type as ContractType) ? raw.contract_type as ContractType : 'other';
  const haystack = norm(text);
  const seen = new Set<string>();
  const findings: Finding[] = [];

  for (const f of raw.findings ?? []) {
    const quote = clip(f.quote, 300);
    if (!quote) continue;
    const entry = f.library_id ? CLAUSE_BY_ID.get(f.library_id) : undefined;
    // Integrity: a library match sets the risk level; otherwise it is a general review.
    const risk: Risk = entry ? entry.risk : (RISKS.includes(f.risk as Risk) ? f.risk as Risk : 'medium');
    const key = entry ? entry.id : norm(quote).slice(0, 80);
    if (seen.has(key)) continue;
    seen.add(key);
    const verified = haystack.includes(norm(quote).replace(/…$/, ''));
    const weight = entry && verified ? RISK_WEIGHT[risk] : Math.round(RISK_WEIGHT[risk] / 2);
    findings.push({
      library_id: entry ? entry.id : null,
      clause: entry ? entry.name : 'Other risk',
      risk,
      confidence: entry && verified ? 'library' : 'review_recommended',
      source: entry ? `Redline clause library: ${entry.name}` : 'General AI review',
      quote,
      quote_verified: verified,
      explanation: clip(f.explanation, 400),
      rewrite: clip(f.rewrite, 900),
      weight,
    });
  }

  const order: Record<Risk, number> = { high: 0, medium: 1, low: 2 };
  findings.sort((a, b) => order[a.risk] - order[b.risk] || b.weight - a.weight);
  const risk = Math.min(99, BASE_RISK + findings.reduce((s, f) => s + f.weight, 0));

  const dates: KeyDate[] = (raw.dates ?? [])
    .map(d => ({
      label: clip(d.label, 120),
      date: /^\d{4}-\d{2}-\d{2}$/.test(String(d.date ?? '')) ? String(d.date) : null,
      when: clip(d.when, 160),
      kind: DATE_KINDS.includes(String(d.kind)) ? String(d.kind) : 'other',
    }))
    .filter(d => d.label && (d.date || d.when))
    .slice(0, 30);

  return {
    contract_type: type,
    contract_label: CONTRACT_TYPES[type].label,
    title: clip(raw.title, 120) || CONTRACT_TYPES[type].label,
    counterparty: clip(raw.counterparty, 120),
    risk,
    level: risk >= 60 ? 'high' : risk >= 30 ? 'medium' : 'low',
    findings: findings.slice(0, 25),
    dates,
    truncated,
  };
}

export function counterOfferPrompt(opts: {
  title: string;
  counterparty: string;
  tone: string;
  findings: Array<{ clause: string; quote: string; rewrite: string }>;
}): string {
  const tone = opts.tone === 'firm' ? 'firm and confident' : opts.tone === 'soft' ? 'warm and collaborative' : 'friendly but clear';
  return [
    `Write a short email the signer can send to ${opts.counterparty || 'the other party'} about the ${opts.title || 'contract'}.`,
    `Tone: ${tone}. Thank them, say they are keen to move forward, then propose these changes as a numbered list.`,
    'For each change, quote the original wording briefly and give the proposed replacement. Keep it under 250 words.',
    'Do not mention Redline, AI, or legal advice. Start with "Subject:" on the first line. Use [Your name] as the signature.',
    '',
    ...opts.findings.map((f, i) => `${i + 1}. ${f.clause}\nOriginal: ${f.quote}\nProposed: ${f.rewrite}`),
  ].join('\n');
}

import { router, json, error, requireAuth, auth, ai, db, increment } from '@appdeploy/sdk';
import { createHash } from 'crypto';

import { realtimeSubscriptionRoutes } from './realtime-subscribers';
import { CLAUSES, CONTRACT_TYPES } from './kb';
import {
  MAX_CHARS,
  REVIEW_SCHEMA,
  REVIEW_SYSTEM,
  reviewPrompt,
  finalize,
  counterOfferPrompt,
} from './engine';
import type { RawReview, Review, Finding, KeyDate } from './engine';

const ANON_DAILY = 8;
const USER_DAILY = 40;
const BENCHMARK_MIN_CONTRACTS = 25;

const hash = (s: string) => createHash('sha256').update(s).digest('hex').slice(0, 24);
const today = () => new Date().toISOString().slice(0, 10);
const scansTable = (userId: string) => `scans_${hash(userId)}`;

function clientIp(event: any): string {
  const fwd = String(event?.headers?.['x-forwarded-for'] ?? '').split(',')[0].trim();
  return fwd || String(event?.requestContext?.http?.sourceIp ?? 'unknown');
}

// One counter per caller per day. Returns false once the daily limit is used up.
async function takeQuota(caller: string, limit: number): Promise<boolean> {
  const id = `${today()}_${hash(caller)}`;
  await db.tx.add('usage', [{ id, n: 0 }]);
  await db.tx.update('usage', [{ id, record: { n: increment(1) } }], { patch: true });
  const [rec] = await db.get<{ n: number }>('usage', [id], { consistent: true });
  return (rec?.n ?? 1) <= limit;
}

interface Profile {
  who?: string;
  city?: string;
  state?: string;
  share_stats?: boolean;
}

async function getProfile(userId: string): Promise<Profile> {
  const [p] = await db.get<Profile>('profiles', [hash(userId)]);
  return p ?? {};
}

// Anonymous clause statistics: contract type, clause id, risk level, state and month.
// No contract text, quotes, names or user ids are stored.
async function recordStats(review: Review, state: string): Promise<void> {
  const type = review.contract_type;
  const libIds = [...new Set(review.findings.map(f => f.library_id).filter((x): x is string => !!x))];
  const ids = [`t_${type}`, ...libIds.map(id => `c_${type}_${id}`)];
  await db.tx.add('clause_counts', ids.map(id => ({ id, n: 0 })));
  await db.tx.update('clause_counts', ids.map(id => ({ id, record: { n: increment(1) } })), { patch: true });
  const month = today().slice(0, 7);
  const events = review.findings.map(f => ({ type, library_id: f.library_id ?? '', risk: f.risk, state: state.slice(0, 40), month }));
  if (events.length) await db.add('clause_events', events.slice(0, 100));
}

// "Seen in 64% of creator deals" once there are enough contracts of that type.
async function benchmarks(review: Review): Promise<Record<string, number>> {
  const type = review.contract_type;
  const libIds = [...new Set(review.findings.map(f => f.library_id).filter((x): x is string => !!x))];
  if (!libIds.length) return {};
  const rows = await db.get<{ n: number }>('clause_counts', [`t_${type}`, ...libIds.map(id => `c_${type}_${id}`)]);
  const total = rows[0]?.n ?? 0;
  if (total < BENCHMARK_MIN_CONTRACTS) return {};
  const out: Record<string, number> = {};
  libIds.forEach((id, i) => {
    const n = rows[i + 1]?.n ?? 0;
    out[id] = Math.round((n / total) * 100);
  });
  return out;
}

async function runReview(text: string, opts: { side?: string; city?: string; state?: string; who?: string }): Promise<Review> {
  const clean = text.replace(/\u0000/g, '').trim();
  const truncated = clean.length > MAX_CHARS;
  const content = truncated ? clean.slice(0, MAX_CHARS) : clean;
  const result = await ai.extract({
    system: REVIEW_SYSTEM,
    prompt: reviewPrompt(opts),
    content,
    schema: REVIEW_SCHEMA,
    maxTokens: 8192,
    temperature: 0.1,
    maxRetries: 2,
  });
  return finalize((result.data ?? {}) as RawReview, content, truncated);
}

function aiFailure(err: unknown) {
  const e = err as { statusCode?: number; responseText?: string };
  console.error('ai failure', e?.statusCode, e?.responseText ?? String(err));
  if (e?.statusCode === 429) return error('Redline is busy right now. Try again in a minute.', 429);
  return error('Redline could not review this contract. Try again.', 502);
}

const str = (v: unknown, n = 200) => String(v ?? '').slice(0, n).trim();

export const handler = router({
  'GET /api/_healthcheck': [async () => json({ message: 'Success' })],

  // Full review. Works signed out (small daily limit); signed-in users get history and the wallet.
  'POST /api/analyze': [async (ctx) => {
    const body = (ctx.body ?? {}) as Record<string, unknown>;
    const text = String(body.text ?? '');
    if (text.trim().length < 80) return error('Paste or upload the full contract text.', 400);

    const user = await auth.getUser(ctx.event);
    const profile = user ? await getProfile(user.userId) : {};
    const allowed = await takeQuota(user ? `u:${user.userId}` : `ip:${clientIp(ctx.event)}`, user ? USER_DAILY : ANON_DAILY);
    if (!allowed) {
      return error(user
        ? 'You have reached today’s review limit. It resets tomorrow.'
        : 'Free reviews for today are used up. Sign in for more.', 429);
    }

    const opts = {
      side: str(body.side, 10),
      who: str(body.who ?? profile.who, 60),
      city: str(body.city ?? profile.city, 80),
      state: str(body.state ?? profile.state, 40),
    };

    let review: Review;
    try {
      review = await runReview(text, opts);
    } catch (err) {
      return aiFailure(err);
    }

    let bench: Record<string, number> = {};
    try {
      bench = await benchmarks(review);
      const share = body.share_stats !== false && profile.share_stats !== false;
      if (share) await recordStats(review, opts.state);
    } catch (err) {
      console.warn('stats skipped', String(err));
    }

    let scanId: string | null = null;
    if (user) {
      const [id] = await db.add(scansTable(user.userId), [{
        name: str(body.name, 160) || review.title,
        title: review.title,
        contract_type: review.contract_type,
        contract_label: review.contract_label,
        counterparty: review.counterparty,
        risk: review.risk,
        level: review.level,
        findings: review.findings,
        dates: review.dates,
        created_at: new Date().toISOString(),
      }]);
      scanId = id;
    }

    return json({ ...review, benchmarks: bench, scan_id: scanId, signed_in: !!user });
  }],

  'POST /api/counter-offer': [async (ctx) => {
    const body = (ctx.body ?? {}) as Record<string, unknown>;
    const findings = (Array.isArray(body.findings) ? body.findings : []).slice(0, 10).map((f: any) => ({
      clause: str(f?.clause, 120),
      quote: str(f?.quote, 300),
      rewrite: str(f?.rewrite, 900),
    })).filter(f => f.quote && f.rewrite);
    if (!findings.length) return error('Pick at least one clause to push back on.', 400);

    const user = await auth.getUser(ctx.event);
    const allowed = await takeQuota(user ? `u:${user.userId}` : `ip:${clientIp(ctx.event)}`, user ? USER_DAILY : ANON_DAILY);
    if (!allowed) return error(user ? 'Daily limit reached. It resets tomorrow.' : 'Sign in to draft more replies today.', 429);

    try {
      const out = await ai.generate({
        system: 'You write clear, polite negotiation emails for people pushing back on contract terms.',
        prompt: counterOfferPrompt({ title: str(body.title, 160), counterparty: str(body.counterparty, 160), tone: str(body.tone, 10), findings }),
        maxTokens: 900,
        temperature: 0.4,
      });
      return json({ email: out.text.trim() });
    } catch (err) {
      return aiFailure(err);
    }
  }],

  'GET /api/me': [requireAuth(), async (ctx) => {
    const profile = await getProfile(ctx.user!.userId);
    return json({ user: { email: ctx.user!.email ?? null, name: ctx.user!.name ?? null }, profile: { share_stats: true, ...profile } });
  }],

  'PUT /api/me': [requireAuth(), async (ctx) => {
    const body = (ctx.body ?? {}) as Record<string, unknown>;
    const profile: Profile = {
      who: str(body.who, 60),
      city: str(body.city, 80),
      state: str(body.state, 40),
      share_stats: body.share_stats !== false,
    };
    await db.tx.update('profiles', [{ id: hash(ctx.user!.userId), record: { ...profile } }]);
    return json({ profile });
  }],

  'GET /api/scans': [requireAuth(), async (ctx) => {
    const { items } = await db.list<Record<string, unknown>>(scansTable(ctx.user!.userId), { limit: 50 });
    items.sort((a, b) => String(b.created_at).localeCompare(String(a.created_at)));
    return json({ scans: items });
  }],

  'DELETE /api/scans/:id': [requireAuth(), async (ctx) => {
    const [ok] = await db.delete(scansTable(ctx.user!.userId), [ctx.params.id]);
    return ok ? json({ deleted: true }) : error('Not found', 404);
  }],

  // Contract wallet: every deadline across the user's saved contracts, soonest first.
  'GET /api/wallet': [requireAuth(), async (ctx) => {
    const { items } = await db.list<{ name?: string; title?: string; dates?: KeyDate[]; findings?: Finding[] }>(scansTable(ctx.user!.userId), { limit: 50 });
    const now = today();
    const entries = items.flatMap(s => (s.dates ?? []).map(d => ({
      scan_id: s.id,
      contract: s.name || s.title || 'Contract',
      label: d.label,
      date: d.date,
      when: d.when,
      kind: d.kind,
      past: !!d.date && d.date < now,
    })));
    entries.sort((a, b) => (a.date ? 0 : 1) - (b.date ? 0 : 1) || String(a.date).localeCompare(String(b.date)));
    return json({ entries });
  }],

  'GET /api/library': [async () => json({
    types: CONTRACT_TYPES,
    clauses: CLAUSES,
  })],

  ...realtimeSubscriptionRoutes,
});

// Connects the page to Redline's backend: sign-in, AI review, counter-offers, saved contracts.
import { api, auth } from '@appdeploy/client';

const cloud = {
  ready: false,
  user: null,
  signIn: () => auth.signInWithRedirect(),
  async signOut() {
    await auth.signOut();
    cloud.user = null;
    emit();
  },
  analyze: payload => api.post('/api/analyze', payload).then(r => r.data),
  counterOffer: payload => api.post('/api/counter-offer', payload).then(r => r.data),
  scans: () => api.get('/api/scans').then(r => r.data),
  wallet: () => api.get('/api/wallet').then(r => r.data),
  deleteScan: id => api.delete('/api/scans/' + encodeURIComponent(id)).then(r => r.data),
  me: () => api.get('/api/me').then(r => r.data),
  saveMe: profile => api.put('/api/me', profile).then(r => r.data),
};

function emit() {
  window.dispatchEvent(new CustomEvent('redline:cloud', { detail: cloud }));
}

window.RedlineCloud = cloud;

auth.getUser()
  .then(user => { cloud.user = user; })
  .catch(() => { cloud.user = null; })
  .finally(() => {
    cloud.ready = true;
    emit();
  });

