    const n = document.createElement('p');
    n.className = 'note';
    n.textContent = e && e.response && e.response.status === 429 ? errMsg(e) : 'The full AI review is unavailable right now, so this is the quick scan.';
    result.prepend(n);
  }
  return true;
}

